#include "raylib.h"
#include <algorithm>
#include <array>
#include <cerrno>
#include <cctype>
#include <cstdio>
#include <fstream>
#include <string>
#include <vector>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

namespace {
struct Config {
    std::string avatar = "avatar/default";
    float scale = 1.0f;
    int direction = 3;
    bool mic = true;
    float threshold = 0.035f;
    int releaseMs = 250;
    bool bounce = true;
    int bouncePx = 4;
    bool bob = false;
    int bobPx = 3;
    int bobMs = 2400;
    bool sway = false;
    int swayPx = 2;
    int swayMs = 3000;
    bool setup = true;
    std::array<std::string,8> expressions{};
};
struct Child { pid_t pid=-1; int fd=-1; };
std::string trim(std::string s){while(!s.empty()&&std::isspace((unsigned char)s.front()))s.erase(s.begin());while(!s.empty()&&std::isspace((unsigned char)s.back()))s.pop_back();return s;}
bool pbool(std::string s,bool f){std::transform(s.begin(),s.end(),s.begin(),[](unsigned char c){return(char)std::tolower(c);});if(s=="1"||s=="true"||s=="yes"||s=="on")return true;if(s=="0"||s=="false"||s=="no"||s=="off")return false;return f;}
const char* dname(int i){static const char* n[]={"horizontal","fourway","quadrants","eightway"};return n[std::clamp(i,0,3)];}
int didx(const std::string&s){if(s=="horizontal")return 0;if(s=="fourway"||s=="4way")return 1;if(s=="quadrants"||s=="quadrant")return 2;return 3;}
std::string edir(){char p[4096]={};ssize_t n=readlink("/proc/self/exe",p,sizeof(p)-1);if(n<=0)return".";p[n]=0;std::string s=p;auto slash=s.find_last_of('/');return slash==std::string::npos?".":s.substr(0,slash);}
std::string join(const std::string&a,const std::string&b){if(!b.empty()&&b[0]=='/')return b;return a=="."?b:a+"/"+b;}
std::vector<std::string> readLines(const std::string&p){std::ifstream f(p);std::vector<std::string>v;std::string s;while(std::getline(f,s))v.push_back(s);return v;}
void apply(Config&c,const std::string&k,const std::string&v){try{if(k=="avatar_dir")c.avatar=v;else if(k=="scale")c.scale=std::clamp(std::stof(v),0.1f,8.0f);else if(k=="direction_mode")c.direction=didx(v);else if(k=="mic_enabled")c.mic=pbool(v,c.mic);else if(k=="mic_threshold")c.threshold=std::clamp(std::stof(v),0.0001f,1.0f);else if(k=="mic_release_ms")c.releaseMs=std::clamp(std::stoi(v),0,5000);else if(k=="talk_bounce")c.bounce=pbool(v,c.bounce);else if(k=="bounce_pixels")c.bouncePx=std::clamp(std::stoi(v),0,200);else if(k=="idle_bob")c.bob=pbool(v,c.bob);else if(k=="idle_bob_pixels")c.bobPx=std::clamp(std::stoi(v),0,200);else if(k=="idle_bob_period_ms")c.bobMs=std::clamp(std::stoi(v),200,30000);else if(k=="idle_sway")c.sway=pbool(v,c.sway);else if(k=="idle_sway_pixels")c.swayPx=std::clamp(std::stoi(v),0,200);else if(k=="idle_sway_period_ms")c.swayMs=std::clamp(std::stoi(v),200,30000);else if(k=="show_setup_on_start")c.setup=pbool(v,c.setup);else if(k.rfind("expression_",0)==0&&k.size()==12&&k[11]>='1'&&k[11]<='8')c.expressions[k[11]-'1']=v;}catch(...){}}
Config load(const std::vector<std::string>&lines){Config c;for(auto&o:lines){auto s=trim(o);if(s.empty()||s[0]=='#'||s[0]==';'||s[0]=='[')continue;auto e=s.find('=');if(e!=std::string::npos)apply(c,trim(s.substr(0,e)),trim(s.substr(e+1)));}return c;}
std::string fstr(float v,int d=3){char b[64];std::snprintf(b,sizeof(b),"%.*f",d,(double)v);return b;}
void setLine(std::vector<std::string>&lines,const std::string&k,const std::string&v){for(auto&o:lines){auto s=trim(o);if(s.empty()||s[0]=='#'||s[0]==';'||s[0]=='[')continue;auto e=s.find('=');if(e!=std::string::npos&&trim(s.substr(0,e))==k){o=k+"="+v;return;}}lines.push_back(k+"="+v);}
void save(const std::string&p,std::vector<std::string>lines,const Config&c,bool skipSetup){setLine(lines,"avatar_dir",c.avatar);setLine(lines,"scale",fstr(c.scale));setLine(lines,"direction_mode",dname(c.direction));setLine(lines,"mic_enabled",c.mic?"true":"false");setLine(lines,"mic_threshold",fstr(c.threshold,4));setLine(lines,"mic_release_ms",std::to_string(c.releaseMs));setLine(lines,"talk_bounce",c.bounce?"true":"false");setLine(lines,"bounce_pixels",std::to_string(c.bouncePx));setLine(lines,"idle_bob",c.bob?"true":"false");setLine(lines,"idle_bob_pixels",std::to_string(c.bobPx));setLine(lines,"idle_bob_period_ms",std::to_string(c.bobMs));setLine(lines,"idle_sway",c.sway?"true":"false");setLine(lines,"idle_sway_pixels",std::to_string(c.swayPx));setLine(lines,"idle_sway_period_ms",std::to_string(c.swayMs));setLine(lines,"show_setup_on_start",skipSetup?"false":(c.setup?"true":"false"));for(int i=0;i<8;++i)setLine(lines,"expression_"+std::to_string(i+1),c.expressions[i]);std::ofstream f(p,std::ios::trunc);for(auto&s:lines)f<<s<<'\n';}
bool hit(Rectangle r){return IsMouseButtonPressed(MOUSE_BUTTON_LEFT)&&CheckCollisionPointRec(GetMousePosition(),r);}
bool button(Rectangle r,const std::string&s,bool en=true){bool h=en&&CheckCollisionPointRec(GetMousePosition(),r);DrawRectangleRec(r,en?(h?Color{215,220,225,255}:Color{235,238,240,255}):Color{205,205,205,255});DrawRectangleLinesEx(r,1,DARKGRAY);int w=MeasureText(s.c_str(),15);DrawText(s.c_str(),(int)(r.x+(r.width-w)/2),(int)(r.y+7),15,en?BLACK:GRAY);return en&&hit(r);}
bool toggle(Rectangle r,const char*s,bool v){DrawRectangleLinesEx(Rectangle{r.x,r.y+2,20,20},1,DARKGRAY);if(v){DrawLine((int)r.x+4,(int)r.y+12,(int)r.x+9,(int)r.y+18,DARKGREEN);DrawLine((int)r.x+9,(int)r.y+18,(int)r.x+17,(int)r.y+6,DARKGREEN);}DrawText(s,(int)r.x+28,(int)r.y+4,15,BLACK);return hit(r)?!v:v;}
bool field(Rectangle r,std::string&v,bool active){if(hit(r))active=true;if(active&&IsMouseButtonPressed(MOUSE_BUTTON_LEFT)&&!CheckCollisionPointRec(GetMousePosition(),r))active=false;if(active){int ch;while((ch=GetCharPressed())>0)if(ch>=32&&ch<=126&&v.size()<480)v.push_back((char)ch);if(IsKeyPressed(KEY_BACKSPACE)&&!v.empty())v.pop_back();if(IsKeyPressed(KEY_ENTER)||IsKeyPressed(KEY_ESCAPE))active=false;}DrawRectangleRec(r,active?Color{255,255,245,255}:WHITE);DrawRectangleLinesEx(r,active?2:1,active?DARKBLUE:GRAY);std::string s=v;while(MeasureText(s.c_str(),15)>(int)r.width-12&&s.size()>3)s.erase(s.begin());DrawText(s.c_str(),(int)r.x+6,(int)r.y+7,15,BLACK);return active;}
bool running(Child&c){if(c.pid<=0)return false;int st=0;pid_t r=waitpid(c.pid,&st,WNOHANG);if(r==0)return true;if(c.fd>=0)close(c.fd);c={};return false;}
bool send(Child&c,const std::string&s){if(c.fd<0)return false;const char*p=s.c_str();size_t n=s.size();while(n){ssize_t w=write(c.fd,p,n);if(w<0){if(errno==EINTR)continue;return false;}p+=w;n-=(size_t)w;}return true;}
bool spawn(const std::string&dir,const std::string&cfg,Child&c){int fds[2];if(pipe(fds)!=0)return false;pid_t p=fork();if(p<0){close(fds[0]);close(fds[1]);return false;}if(p==0){close(fds[1]);dup2(fds[0],STDIN_FILENO);close(fds[0]);chdir(dir.c_str());int log=open("V_mini_me_launcher.log",O_WRONLY|O_CREAT|O_APPEND,0644);if(log>=0){dup2(log,STDOUT_FILENO);dup2(log,STDERR_FILENO);close(log);}execl("./V_mini_me","V_mini_me",cfg.c_str(),(char*)nullptr);_exit(127);}close(fds[0]);c.pid=p;c.fd=fds[1];return true;}
std::string label(const std::string&s){if(s.empty())return"[empty]";auto p=s.find_last_of('/');std::string n=p==std::string::npos?s:s.substr(p+1);if(n.size()>12)n.resize(12);return n;}
}
int main(){std::string dir=edir(),core=join(dir,"V_mini_me"),cfg=join(dir,"config.ini"),tmpName=".vmini_launcher_runtime.ini",tmp=join(dir,tmpName);auto lines=readLines(cfg);Config c=load(lines);InitWindow(930,720,"V_mini_me optional launcher");SetTargetFPS(30);Child child;bool aedit=false,eedit=false;int slot=0;std::string status=access(core.c_str(),X_OK)==0?"Ready":"V_mini_me not found beside launcher";while(!WindowShouldClose()){bool run=running(child);BeginDrawing();ClearBackground(Color{246,246,246,255});DrawText("V_mini_me - optional Linux launcher",22,18,25,BLACK);DrawText(status.c_str(),22,50,15,run?DARKGREEN:DARKGRAY);DrawText("Avatar folder",22,92,15,BLACK);aedit=field(Rectangle{170,84,735,32},c.avatar,aedit);DrawText("Scale",22,134,15,BLACK);if(button(Rectangle{170,126,34,28},"-"))c.scale=std::max(.1f,c.scale-.1f);DrawText(fstr(c.scale,2).c_str(),216,134,15,BLACK);if(button(Rectangle{280,126,34,28},"+"))c.scale=std::min(8.f,c.scale+.1f);DrawText("Direction",370,134,15,BLACK);if(button(Rectangle{475,126,180,28},dname(c.direction)))c.direction=(c.direction+1)%4;c.mic=toggle(Rectangle{22,174,180,26},"Microphone",c.mic);DrawText(("Threshold "+fstr(c.threshold,4)).c_str(),220,180,15,BLACK);if(button(Rectangle{390,172,34,28},"-"))c.threshold=std::max(.0001f,c.threshold-.005f);if(button(Rectangle{430,172,34,28},"+"))c.threshold=std::min(1.f,c.threshold+.005f);DrawText(("Release "+std::to_string(c.releaseMs)+" ms").c_str(),500,180,15,BLACK);if(button(Rectangle{690,172,34,28},"-"))c.releaseMs=std::max(0,c.releaseMs-50);if(button(Rectangle{730,172,34,28},"+"))c.releaseMs=std::min(5000,c.releaseMs+50);c.bounce=toggle(Rectangle{22,216,190,26},"Talking bounce",c.bounce);DrawText(("Pixels "+std::to_string(c.bouncePx)).c_str(),220,222,15,BLACK);if(button(Rectangle{330,214,34,28},"-"))c.bouncePx=std::max(0,c.bouncePx-1);if(button(Rectangle{370,214,34,28},"+"))c.bouncePx=std::min(200,c.bouncePx+1);c.bob=toggle(Rectangle{22,258,180,26},"Idle bob",c.bob);DrawText(("Pixels "+std::to_string(c.bobPx)).c_str(),220,264,15,BLACK);if(button(Rectangle{330,256,34,28},"-"))c.bobPx=std::max(0,c.bobPx-1);if(button(Rectangle{370,256,34,28},"+"))c.bobPx=std::min(200,c.bobPx+1);DrawText(("Period "+std::to_string(c.bobMs)+" ms").c_str(),440,264,15,BLACK);if(button(Rectangle{650,256,34,28},"-"))c.bobMs=std::max(200,c.bobMs-100);if(button(Rectangle{690,256,34,28},"+"))c.bobMs=std::min(30000,c.bobMs+100);c.sway=toggle(Rectangle{22,300,180,26},"Idle sway",c.sway);DrawText(("Pixels "+std::to_string(c.swayPx)).c_str(),220,306,15,BLACK);if(button(Rectangle{330,298,34,28},"-"))c.swayPx=std::max(0,c.swayPx-1);if(button(Rectangle{370,298,34,28},"+"))c.swayPx=std::min(200,c.swayPx+1);DrawText(("Period "+std::to_string(c.swayMs)+" ms").c_str(),440,306,15,BLACK);if(button(Rectangle{650,298,34,28},"-"))c.swayMs=std::max(200,c.swayMs-100);if(button(Rectangle{690,298,34,28},"+"))c.swayMs=std::min(30000,c.swayMs+100);c.setup=toggle(Rectangle{22,342,300,26},"Terminal setup on direct start",c.setup);DrawLine(22,382,908,382,LIGHTGRAY);DrawText("Quick Expressions",22,398,20,BLACK);if(button(Rectangle{22,432,34,30},"<"))slot=(slot+7)%8;DrawText(("Slot "+std::to_string(slot+1)).c_str(),68,440,15,BLACK);if(button(Rectangle{130,432,34,30},">"))slot=(slot+1)%8;eedit=field(Rectangle{175,430,610,34},c.expressions[slot],eedit);if(button(Rectangle{795,432,110,34},"Use avatar"))c.expressions[slot]=c.avatar;DrawText("Live expression buttons",22,485,15,BLACK);for(int i=0;i<8;++i){Rectangle r{22.f+(i%4)*220.f,510.f+(i/4)*38.f,205.f,30.f};bool en=run&&!c.expressions[i].empty();if(button(r,std::to_string(i+1)+": "+label(c.expressions[i]),en)){if(send(child,"e\n"+std::to_string(i+1)+"\n"))status="Expression sent";}}DrawLine(22,598,908,598,LIGHTGRAY);if(button(Rectangle{22,620,120,40},"Save")){save(cfg,lines,c,false);lines=readLines(cfg);status="Saved config.ini";}if(button(Rectangle{155,620,160,40},run?"Restart":"Start + controls",access(core.c_str(),X_OK)==0)){save(cfg,lines,c,false);lines=readLines(cfg);save(tmp,lines,c,true);if(run){send(child,"q\n");status="Stop requested; press Start again";}else if(spawn(dir,tmpName,child))status="Avatar started";else status="Could not start";}if(button(Rectangle{328,620,100,40},"Reload",run)){if(send(child,"r\n"))status="Reload sent";}if(button(Rectangle{440,620,100,40},"Stop",run)){if(send(child,"q\n"))status="Stop requested";}DrawText(run?("Runtime PID "+std::to_string(child.pid)).c_str():"Runtime stopped",22,682,15,DARKGRAY);EndDrawing();}if(child.fd>=0)close(child.fd);CloseWindow();return 0;}
